// These presets contain colors only. Every target uses the same bounds,
// typography, positions, effects and visibility options from EnemyHealthOptions.
internal sealed class TargetColorPalette {
    public string Low,Medium,High,Name,Value,Distance,Species,Lock;
    internal TargetColorPalette Copy(){return (TargetColorPalette)MemberwiseClone();}
    internal static TargetColorPalette Capture(EnemyHealthOptions o){return new TargetColorPalette{Low=o.Bar.LowColor,Medium=o.Bar.MediumColor,High=o.Bar.HighColor,Name=o.Name.Color,Value=o.Bar.TextColor,Distance=o.Details.DistanceText.Color,Species=o.Details.SpeciesText.Color,Lock=o.LockText.Color};}
    internal void Apply(EnemyHealthOptions o){o.Bar.LowColor=Low;o.Bar.MediumColor=Medium;o.Bar.HighColor=High;o.Name.Color=Name;o.Bar.TextColor=Value;o.Details.DistanceText.Color=Distance;o.Details.SpeciesText.Color=Species;o.LockText.Color=Lock;}
    internal static TargetColorPalette Defaults(EnemyHealthOptions o,int kind){var p=Capture(o);p.Low=p.Medium=p.High=kind==1?"#EF865F":kind==3?"#8CBEEA":"#65CBB0";p.Name=p.Medium;return p;}
    internal void Normalize(TargetColorPalette fallback){if(!EnergyBarOptions.ValidColor(Low))Low=fallback.Low;if(!EnergyBarOptions.ValidColor(Medium))Medium=fallback.Medium;if(!EnergyBarOptions.ValidColor(High))High=fallback.High;if(!EnergyBarOptions.ValidColor(Name))Name=fallback.Name;if(!EnergyBarOptions.ValidColor(Value))Value=fallback.Value;if(!EnergyBarOptions.ValidColor(Distance))Distance=fallback.Distance;if(!EnergyBarOptions.ValidColor(Species))Species=fallback.Species;if(!EnergyBarOptions.ValidColor(Lock))Lock=fallback.Lock;}
}

internal sealed class EnemyHealthOptions {
    public EnergyBarOptions Bar=new EnergyBarOptions{Enabled=true,AutoHide=false,DynamicColors=false,MediumColor="#EB423D",LowColor="#EB423D",HighColor="#EB423D",CurrentText=true,MaximumText=true,PercentageText=true,CurrentPosition=3,MaximumPosition=3,PercentagePosition=5,TextSize=14,TrackOpacity=140,CurrentOffsetY=8,MaximumOffsetY=8,PercentageOffsetY=8};
    public Rectangle Bounds=new Rectangle(750,145,420,6);
    public bool OnlyLocked=false;public EnemyNameOptions LockText=new EnemyNameOptions{Marker=false,Bold=false,FontSize=12,Position=2,OffsetX=-5,OffsetY=-36,Color="#D2D9DB"};public EnemyNameOptions Name=new EnemyNameOptions();public EnemyDetailOptions Details=new EnemyDetailOptions();public bool SelfHighlight=false;public string SelfColor="#EF986B",SelfNameColor="#B7DEED";
    public TargetColorPalette EnemyPlayerColors,NeutralPlayerColors,NeutralNpcColors;
