    internal EnemyHealthOptions ForPalette(int kind){var o=Copy();if(kind>0)Colors(kind).Apply(o);return o;}
    internal void StoreColors(int kind,TargetColorPalette colors){if(kind==1)EnemyPlayerColors=colors.Copy();else if(kind==2)NeutralPlayerColors=colors.Copy();else if(kind==3)NeutralNpcColors=colors.Copy();else colors.Apply(this);}
    internal static EnemyHealthOptions TargetDefaults(){return new EnemyHealthOptions{Details=new EnemyDetailOptions{Level=false,BaseLevel=false,Distance=false,Species=false},SelfHighlight=true,Bounds=new Rectangle(750,230,240,4),Bar=new EnergyBarOptions{Enabled=true,AutoHide=false,DynamicColors=false,LowColor="#3D9FCE",MediumColor="#3D9FCE",HighColor="#3D9FCE",CurrentText=false,MaximumText=false,PercentageText=false,TrackOpacity=140},Name=new EnemyNameOptions{FontSize=14,Bold=false,Marker=false,Color="#B7DEED",Position=0,OffsetX=-20,OffsetY=0}};}
    internal EnemyHealthOptions Copy(){return new EnemyHealthOptions{Bar=Bar.Copy(),Bounds=Bounds,OnlyLocked=OnlyLocked,LockText=LockText.Copy(),Name=Name.Copy(),Details=Details.Copy(),SelfHighlight=SelfHighlight,SelfColor=SelfColor,SelfNameColor=SelfNameColor,EnemyPlayerColors=EnemyPlayerColors==null?null:EnemyPlayerColors.Copy(),NeutralPlayerColors=NeutralPlayerColors==null?null:NeutralPlayerColors.Copy(),NeutralNpcColors=NeutralNpcColors==null?null:NeutralNpcColors.Copy()};}
    internal void Normalize(){if(LockText==null)LockText=new EnemyHealthOptions().LockText;LockText.Normalize();LockText.Marker=false;if(Bar==null)Bar=new EnemyHealthOptions().Bar;Bar.Normalize();Bar.AutoHide=false;if(!EnergyBarOptions.ValidColor(SelfColor))SelfColor="#EF986B";if(!EnergyBarOptions.ValidColor(SelfNameColor))SelfNameColor="#B7DEED";if(Details==null)Details=new EnemyDetailOptions();Details.Normalize();if(Name==null)Name=new EnemyNameOptions();Name.Normalize();if(EnemyPlayerColors!=null)EnemyPlayerColors.Normalize(TargetColorPalette.Defaults(this,1));if(NeutralPlayerColors!=null)NeutralPlayerColors.Normalize(TargetColorPalette.Defaults(this,2));if(NeutralNpcColors!=null)NeutralNpcColors.Normalize(TargetColorPalette.Defaults(this,3));Bounds=new Rectangle(Math.Max(-100000,Math.Min(100000,Bounds.X)),Math.Max(-100000,Math.Min(100000,Bounds.Y)),Math.Max(80,Math.Min(2400,Bounds.Width)),Math.Max(3,Math.Min(80,Bounds.Height)));}
    internal static EnemyHealthOptions Read(Dictionary<string,object> cfg,string section="enemyHealth"){object value;var o=section=="enemyTarget"?TargetDefaults():new EnemyHealthOptions();if(cfg.TryGetValue(section,out value))try{o=new JavaScriptSerializer().ConvertToType<EnemyHealthOptions>(value)??o;}catch(ArgumentException){}var legacy=value as Dictionary<string,object>;if(section=="enemyTarget"&&legacy!=null&&!legacy.ContainsKey("Details"))o.Details=TargetDefaults().Details;if(section=="enemyTarget"&&legacy!=null&&!legacy.ContainsKey("SelfNameColor")&&o.Name!=null)o.SelfNameColor=o.Name.Color;if(section=="enemyTarget"&&legacy!=null&&!legacy.ContainsKey("SelfHighlight"))o.SelfHighlight=true;if(legacy!=null&&!legacy.ContainsKey("Name")&&o.Bar!=null)o.Name.FontSize=Math.Max(14,Math.Min(36,(int)Math.Round(o.Bar.TextSize*1.5)));if(o.Bar!=null&&!o.Bar.DynamicColors&&o.Bar.MediumColor=="#BD333B"&&o.Bar.LowColor=="#BD333B"&&o.Bar.HighColor=="#BD333B"){o.Bar.MediumColor=o.Bar.LowColor=o.Bar.HighColor="#EB423D";if(o.Bar.CurrentOffsetY==0&&o.Bar.MaximumOffsetY==0&&o.Bar.PercentageOffsetY==0)o.Bar.CurrentOffsetY=o.Bar.MaximumOffsetY=o.Bar.PercentageOffsetY=8;}o.Normalize();return o;}
}

internal static class EnemyNames {
    public sealed class Entry {public string en {get;set;}public string es {get;set;}}
    static readonly Dictionary<string,Entry> names=Load();
    static Dictionary<string,Entry> Load(){try{using(var stream=typeof(EnemyNames).Assembly.GetManifestResourceStream("Aion2NpcNames.json")){if(stream==null)return new Dictionary<string,Entry>();using(var reader=new StreamReader(stream))return new JavaScriptSerializer{MaxJsonLength=4000000}.Deserialize<Dictionary<string,Entry>>(reader.ReadToEnd());}}catch(IOException){return new Dictionary<string,Entry>();}catch(ArgumentException){return new Dictionary<string,Entry>();}}
    internal static bool Known(uint id){return names.ContainsKey(id.ToString(CultureInfo.InvariantCulture));}
    internal static string Name(uint id,string language,bool target=false){Entry entry;if(names.TryGetValue(id.ToString(CultureInfo.InvariantCulture),out entry)&&entry!=null&&!string.IsNullOrEmpty(entry.en))return language=="es"&&!string.IsNullOrEmpty(entry.es)?entry.es:entry.en;return target?(language=="es"?"Objetivo desconocido":"Unknown target"):(language=="es"?"Enemigo":"Enemy");}
}

// Passive, bounded state on the existing decoder. No selected-target memory read.
// 3438 was validated with Tab A/B and clear; 3538 also carries NPC aggro and
// is deliberately not used. Cast aim precedes area impacts and passive procs.
// The two recorded normal 1v1 arenas announce two one-player teams. This
// bounded reader accepts only those complete observed layouts; it does not
// scan an arbitrary name list or infer an opponent from our attacks.
internal static class NeutralNpcCatalogue {
    static readonly Dictionary<string,int[]> table=Load();
    static Dictionary<string,int[]> Load(){try{using(var stream=typeof(NeutralNpcCatalogue).Assembly.GetManifestResourceStream("NeutralNpcCatalogue.json")){if(stream==null)return new Dictionary<string,int[]>();using(var reader=new StreamReader(stream))return new JavaScriptSerializer().Deserialize<Dictionary<string,int[]>>(reader.ReadToEnd())??new Dictionary<string,int[]>();}}catch(IOException){return new Dictionary<string,int[]>();}catch(ArgumentException){return new Dictionary<string,int[]>();}}
    internal static bool Known(uint npc,uint map){int[] maps;if(!table.TryGetValue(npc.ToString(CultureInfo.InvariantCulture),out maps)||maps==null)return false;foreach(int value in maps)if(value>0&&(uint)value==map)return true;return false;}
}

internal static class TargetRelations {
    internal sealed class Member {internal int Team,Server,Faction;internal uint ClassCode;internal string Name;}
    internal sealed class Arena {internal uint Content;internal Member[] Members;internal double Time;}
    static bool Room(int p,int end,int n){return p>=0&&n>=0&&p<=end-n;}
    internal static bool ParseArena(byte[] b,int start,int end,out Arena arena){
        arena=null;if(b==null||start<0||end>b.Length||end-start<150||end-start>512||b[start]!=0x19||b[start+1]!=0xe3)return false;int p=start+2;uint instance;if(!DpsSignal.Var(b,ref p,end,out instance)||instance==0||instance>10000000||!Room(p,end,17)||BitConverter.ToUInt32(b,p)!=1)return false;p+=4;ulong content=BitConverter.ToUInt64(b,p);p+=8;if(content!=11&&content!=22)return false;p+=4;if(b[p++]!=2)return false;var members=new Member[2];
        for(int n=0;n<2;n++){
            if(!Room(p,end,22))return false;int team=b[p++];if(team<1||team>2||(n>0&&team==members[0].Team))return false;p+=12;if(b[p++]!=1||BitConverter.ToUInt64(b,p)!=0)return false;p+=8;
            if(!Room(p,end,9))return false;ulong id=BitConverter.ToUInt64(b,p);p+=8;int server=(int)(id>>48),length=b[p++];if(server/1000!=1&&server/1000!=2||length<2||length>24||!Room(p,end,length+13+27))return false;string name;try{name=new System.Text.UTF8Encoding(false,true).GetString(b,p,length);}catch(System.Text.DecoderFallbackException){return false;}foreach(char c in name)if(char.IsControl(c))return false;p+=length;uint code=BitConverter.ToUInt32(b,p);p+=4;int faction=b[p++];uint level=BitConverter.ToUInt32(b,p);p+=4;if(code<5||code>36||faction!=server/1000||level<1||level>200||BitConverter.ToUInt32(b,p)!=0)return false;p+=4;
            if(BitConverter.ToUInt16(b,p)!=server||b[p+10]!=1||b[p+26]!=0)return false;p+=27;members[n]=new Member{Team=team,Server=server,Faction=faction,ClassCode=code,Name=name};if(n>0&&members[0].Name==name)return false;
        }
        if(p!=end)return false;arena=new Arena{Content=(uint)content,Members=members};return true;
    }
    internal static bool ArenaMap(uint map){return map==60||map==61;}
    internal static int Kind(uint map,int ownFaction,string ownName,int ownServer,uint ownClass,Arena arena,string name,int faction,uint code,out string source){
        source="Unclassified";if(ArenaMap(map)){
            if(arena==null||(map==60?arena.Content!=11:arena.Content!=22))return -1;Member self=null,target=null;foreach(var m in arena.Members){if(m.Name==ownName&&m.Server==ownServer&&m.Faction==ownFaction&&m.ClassCode==ownClass)self=m;if(m.Name==name&&m.Faction==faction&&m.ClassCode==code)target=m;}
            if(self==null||target==null||self==target)return -1;source="Arena teams";return self.Team==target.Team?2:1;
        }
        // Only the world map and Abyss observed in the controlled tests are
        // enabled here. Other map modes keep the base palette. Overworld duel
        // rules need a separate relationship control before being extended.
        if(map!=1010&&map!=20||ownFaction<1||ownFaction>2||faction<1||faction>2)return -1;source="Faction";return ownFaction==faction?2:1;
    }
}

internal sealed class EnemyHealthSignal {
