    internal static bool Fresh(Sample s,double utc){return s!=null&&s.Current>0&&s.Maximum>0&&Math.Max(0,utc-s.Traffic)<=10;}
    internal Sample Actor(string key,uint actor){lock(gate){Flow f;Sample s;if(!flows.TryGetValue(key,out f)||actor==f.Self||!f.Entities.TryGetValue(actor,out s))return null;return Clone(s,f,key,false);}}
    internal Sample Read(){lock(gate){Flow f;Sample s;if(selfFlow==null||!flows.TryGetValue(selfFlow,out f)||!f.Entities.TryGetValue(f.Locked!=0?f.Locked:f.Soft,out s)||s.Actor==f.Self)return null;return Clone(s,f,selfFlow,f.Locked!=0);}}
    Sample Clone(Sample s,Flow f,string key,bool locked){double now=DpsHistory.UtcNow();bool exact=ClientPositions!=null&&ClientPositions.Enabled;var reading=exact?ClientPositions.Read(key,now):null;var position=exact?(reading==null?new EnemyDetailReader.Position():reading.Position):f.SelfPosition;double? distance=EnemyDetailReader.Distance(position,s.Position,now,exact);string relation=null;int kind=s.IsPlayer?TargetRelations.Kind(f.Map,f.SelfFaction,f.SelfName,f.SelfServer,f.SelfClass,f.Arena,s.Name,s.Faction,s.ClassCode,out relation):(NeutralNpcCatalogue.Known(s.Npc,f.Map)?3:0);if(kind==3)relation="Confirmed neutral NPC catalogue";return new Sample{Actor=s.Actor,Npc=s.Npc,Current=s.Current,Maximum=s.Maximum,Time=s.Time,Traffic=f.Traffic,Flow=key,Locked=locked,BaseLevel=s.BaseLevel,AdjustedLevel=s.IsPlayer?null:EnemyDetailReader.DisplayLevel(f.SelfLevel,s.BaseLevel),Name=s.Name,IsPlayer=s.IsPlayer,RelationCandidate=s.RelationCandidate,Faction=s.Faction,ClassCode=s.ClassCode,ColorKind=kind,RelationshipSource=relation,Position=s.Position,Distance=distance,DistanceStatus=exact?(reading==null?ClientPositions.ReadingStatus:distance.HasValue?"Exact distance live":"No confirmed enemy position"):!position.Known?"No confirmed player position":!s.Position.Known?"No confirmed enemy position":Math.Max(0,now-position.Time)>5?"Player position older than five seconds":"Confirmed positions"};}
    static readonly int[] DescriptionBits={2,4,8,16},DescriptionSizes={1,1,5,1},StateBits={1,2,4,8,16,32},StateSizes={12,4,2,12,12,4};
    static bool Skip(ref int p,int end,int n){if(n<0||p>end-n)return false;p+=n;return true;}
    // Validates the bounded spawn prefix and its explicit initial/current max.
    // Unknown tails do not provide level, category, or a fabricated maximum.
    internal static bool Spawn(byte[] b,int start,int end,out Sample sample){sample=null;int p=start+2;uint actor,code,hp,max,n;EnemyDetailReader.Position position;int outer=0;if(!DpsSignal.Var(b,ref p,end,out actor)||actor==0||p>end-2)return false;outer=BitConverter.ToUInt16(b,p);p+=2;if(p>=end)return false;int desc=b[p++];if(desc>31)return false;if((desc&1)!=0&&(!DpsSignal.Var(b,ref p,end,out n)||n>160||!Skip(ref p,end,(int)n)))return false;if(p+4>end)return false;code=BitConverter.ToUInt32(b,p);p+=4;if(code<2000000||code>=3000000)return false;for(int i=0;i<DescriptionBits.Length;i++)if((desc&DescriptionBits[i])!=0&&!Skip(ref p,end,DescriptionSizes[i]))return false;if(p+2>end)return false;int state=BitConverter.ToUInt16(b,p);p+=2;EnemyDetailReader.Coordinates(b,p,end,out position);if(!Skip(ref p,end,18))return false;for(int i=0;i<StateBits.Length;i++)if((state&StateBits[i])!=0&&!Skip(ref p,end,StateSizes[i]))return false;if(!Skip(ref p,end,1)||!DpsSignal.Var(b,ref p,end,out hp)||!DpsSignal.Var(b,ref p,end,out max)||max==0||max>1000000000||hp>max||!Skip(ref p,end,52))return false;sample=new Sample{Actor=actor,Npc=code,Current=hp,Maximum=max,Position=position,BaseLevel=EnemyDetailReader.BaseLevel(b,p,end,outer,state)};return true;}
    internal static bool Points(byte[] b,int start,int end,out uint actor,out uint? current,out uint? maximum,out bool energy){actor=0;current=maximum=null;energy=false;int p=start+2;if(!DpsSignal.Var(b,ref p,end,out actor)||actor==0||p>=end)return false;int flags=b[p++];if(flags>3)return false;for(int width=4;width<=8;width+=4)if((flags&(width==4?1:2))!=0){uint count;if(!DpsSignal.Var(b,ref p,end,out count)||count>(end-p)/(width+1))return false;for(uint i=0;i<count;i++){int kind=b[p++];if(width==4&&kind==3){if(energy||actor>int.MaxValue||BitConverter.ToUInt32(b,p)>100000000)return false;energy=true;}if(width==8&&(kind==0||kind==7)){long v=BitConverter.ToInt64(b,p);if(v<0||v>1000000000)return false;if(kind==0)current=(uint)v;else maximum=(uint)v;}p+=width;}}return p==end;}
    internal static bool Selection(byte[] b,int start,int end,out uint actor){actor=0;int p=start+2;return end-start>=6&&b[p++]==0&&b[p++]==0&&b[p++]==0&&DpsSignal.Var(b,ref p,end,out actor)&&p==end&&actor<=10000000;}
    internal static bool Aim(byte[] b,int start,int end,out uint source,out uint target,out uint skill){source=target=skill=0;int p=start+2;if(!DpsSignal.Var(b,ref p,end,out source)||source==0||!Skip(ref p,end,1)||p+6>end)return false;skill=BitConverter.ToUInt32(b,p);p+=4;byte flags=b[p+1];p+=2;if(!DpsSignal.Var(b,ref p,end,out target)||target==0||target==source||p+4>end)return false;float facing=BitConverter.ToSingle(b,p);p+=4;if(float.IsNaN(facing)||float.IsInfinity(facing)||Math.Abs(facing)>720)return false;if((flags&2)!=0){if(p+12>end)return false;for(int i=0;i<3;i++){float v=BitConverter.ToSingle(b,p+i*4);if(float.IsNaN(v)||float.IsInfinity(v)||Math.Abs(v)>10000000)return false;}}return skill/1000000>=11&&skill/1000000<=19;}
    static bool Primary(Flow f,uint skill){return skill%100!=7&&skill%100!=8&&skill%100!=9&&!DpsSignal.HealingSkill(skill)&&!SkillCatalogue.Shared.IsNonDamage(skill)&&(f.Skills.Contains(skill)||skill%100>=10&&skill%100<=69);}
    // Independent bounded quotas: observing or refreshing players must never
    // evict a stationary NPC which the client may not announce again.
    void Trim(Flow f,uint incoming,bool player){Sample existing;if(f.Entities.TryGetValue(incoming,out existing)&&existing.IsPlayer==player)return;int count=0;uint remove=0;double oldest=double.MaxValue;foreach(var pair in f.Entities){if(pair.Value.IsPlayer!=player)continue;count++;if(pair.Key!=f.Locked&&pair.Key!=f.Soft&&pair.Value.Time<oldest){remove=pair.Key;oldest=pair.Value.Time;}}if(count>=512&&remove!=0)f.Entities.Remove(remove);}
    internal object CacheStatus {get{lock(gate){Flow f;int npcs=0,players=0;uint selected=0;if(selfFlow!=null&&flows.TryGetValue(selfFlow,out f)){selected=f.Locked!=0?f.Locked:f.Soft;foreach(var s in f.Entities.Values)if(s.IsPlayer)players++;else npcs++;return new{npcProfiles=npcs,playerProfiles=players,limitPerType=512,selectedActor=selected,selectedProfileKnown=f.Entities.ContainsKey(selected)};}return new{npcProfiles=0,playerProfiles=0,limitPerType=512,selectedActor=0u,selectedProfileKnown=false};}}}

    internal void Consume(byte[] b,int start,int end,double time,string key){if(!enabled||b==null||start<0||end>b.Length||end-start<2||end-start>65536||key==null||double.IsNaN(time)||double.IsInfinity(time))return;bool changed=false;lock(gate){if(!enabled)return;Flow f;if(!flows.TryGetValue(key,out f)){if(flows.Count>=4){string remove=null;double oldest=double.MaxValue;foreach(var pair in flows)if(pair.Key!=selfFlow&&pair.Value.Traffic<oldest){remove=pair.Key;oldest=pair.Value.Traffic;}if(remove==null)return;flows.Remove(remove);}flows[key]=f=new Flow();}if(f.Traffic>0&&time-f.Traffic>30){f.Entities.Clear();f.Locked=f.Soft=f.Self=0;f.SelfFaction=f.SelfServer=0;f.SelfName=null;f.SelfClass=0;f.Arena=null;f.SelfLevel=0;f.SelfPosition=new EnemyDetailReader.Position();f.Skills.Clear();if(selfFlow==key)selfFlow=null;changed=true;}f.Traffic=Math.Max(f.Traffic,time);int op=(b[start]<<8)|b[start+1],p=start+2;uint actor,source,target,skill;uint? current,max;bool energy;string name;byte role;EnemyDetailReader.Position fPosition;
